    def stripes(axis):
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        return [i for i in range(n)
                if all(grid[i][j] == grid[i][0] for j in range(m)) if axis == 0] if False else []

    # Dividers are rows/columns that are constant, apart from intersections
    # with perpendicular dividers. Detect them by their dominant color.
