        if count >= h - 2:
            col_colors.append((c, color))

    def pick(n, dividers):
        chosen = []
        prev = -1
        for i, _ in dividers:
            if i > prev + 1:
                chosen.append(prev + 1)
            chosen.append(i)
            prev = i
        if prev < n - 1:
            chosen.append(prev + 1)
        return chosen

    rows = pick(h, row_colors)
    cols = pick(w, col_colors)
    return [[grid[r][c] for c in cols] for r in rows]
